mapper.select:
SELECT COUNT(*) FROM NOTICE
STATUS='공개'
AND NOTICE_TYPE = #{category}

SELECT * FROM ( SELECT ROWNUM AS rnum, n.* FROM ( SELECT NOTICE_CODE AS noticeCode, TITLE AS title, CONTENT AS content, NOTICE_TYPE AS noticeType, TO_CHAR(INPUT_DATE, 'YYYY.MM.DD') AS noticeDate FROM NOTICE
STATUS='공개'
AND NOTICE_TYPE = #{category}
ORDER BY NOTICE_CODE DESC ) n WHERE ROWNUM <= #{endNum} ) WHERE rnum >= #{startNum}
